mapper.select:
select cohort_id, cohort_name, cohort_year, is_current, status, create_by, create_time, update_by, update_time, remark
from qt_cohort

    and status = #{status}
    and cohort_year = #{cohortYear}

order by is_current desc, cohort_year desc, cohort_id desc

mapper.update:
update qt_cohort
cohort_name = #{cohortName}, cohort_year = #{cohortYear}, is_current = #{isCurrent}, status = #{status}, update_by = #{updateBy}, update_time = now()
where cohort_id = #{cohortId}

update qt_member_record
role_category = #{roleCategory}, member_status = #{memberStatus}, join_time = #{joinTime}, retain_flag = #{retainFlag}, update_by = #{updateBy}, update_time = now()
where record_id = #{recordId}
